const vt = $input.first().json;

const original = $('If1').first().json;

return [{
  json: {
    scan_id: original.scan_id,
    indicator_type: original.indicator_type,
    value: original.value,
    vt_data: vt
  }
}];

const original = $('Code in JavaScript1').first().json;
const lookup = $input.first().json;

// Detect Supabase failure — continueRegularOutput puts error in $json.error
if (lookup && lookup.error !== undefined) {
  return [{
    json: {
      ...original,
      community_intelligence_error: true,
      community_intelligence_error_message: typeof lookup.error === 'string' ? lookup.error : JSON.stringify(lookup.error)
    }
  }];
}

// A real match has report_count >= 1; alwaysOutputData gives {} on no match
const reportCount = (lookup && lookup.report_count !== undefined && lookup.report_count !== null)
  ? Number(lookup.report_count)
  : 0;
const hasMatch = reportCount > 0;

const community_intelligence = hasMatch
  ? {
      indicator_type: lookup.indicator_type || original.indicator_type || null,
      normalized_value: lookup.normalized_value || original.value || null,
      previously_reported: true,
      report_count: reportCount,
      first_seen: lookup.first_seen || null,
      last_seen: lookup.last_seen || null
    }
  : {
      indicator_type: original.indicator_type || null,
      normalized_value: original.value || null,
      previously_reported: false,
      report_count: 0,
      first_seen: null,
      last_seen: null
    };

return [{
  json: {
    ...original,
    community_intelligence
  }
}];

const items = $input.all();

return items.map(item => {
  const d = item.json;

  const vt = d.vt_data?.data;
  const status = vt?.attributes?.status;

  // VirusTotal has not finished scanning yet
  if (status !== "completed") {
    return {
      json: {
        ...d,
        vt_status: status || "unknown",
        malicious: 0,
        suspicious: 0,
        harmless: 0,
        undetected: 0,
        risk_score: null,
        verdict: "ANALYZING"
      }
    };
  }

  const stats = vt.attributes.stats || {};

  const malicious = Number(stats.malicious || 0);
  const suspicious = Number(stats.suspicious || 0);
  const harmless = Number(stats.harmless || 0);
  const undetected = Number(stats.undetected || 0);

  const risk_score = Math.min(
    100,
    malicious * 30 + suspicious * 15
  );

  let verdict;

  if (risk_score >= 70) {
    verdict = "SCAM";
  } else if (risk_score >= 40) {
    verdict = "SUSPICIOUS";
  } else {
    verdict = "SAFE";
  }

  return {
    json: {
      ...d,
      malicious,
      suspicious,
      harmless,
      undetected,
      risk_score,
      verdict,
      vt_status: "completed"
    }
  };
});

const d = $('Update a row').first().json;

const r = $('Risk Engine').first().json;

if (d.verdict === "ANALYZING") {
  const ci_a = r.community_intelligence || null;
  return [{
    json: {
      ...d,
      community_intelligence: ci_a,
      community_section_text: '',
      response: `🔄 ANALYZING

🔗 URL:
${Array.isArray(d.urls) ? d.urls.join("\n") : d.value || "Unknown"}

🛡️ VirusTotal is still processing this URL.

Please try again in a few seconds.

⚠️ Do not open or interact with this link.`
    }
  }];
}

const urls = Array.isArray(d.urls)
  ? d.urls
  : (r.value ? [r.value] : JSON.parse(d.urls || "[]"));

const response = `🚨 ${d.verdict}

🔗 URL:
${urls.join("\n")}

⚠️ Risk Score: ${d.risk_score}/100

🎯 Type: ${d.scam_type || "Unknown"}

🛡️ VirusTotal:

• Malicious: ${r.malicious}
• Suspicious: ${r.suspicious}
• Harmless: ${r.harmless}
• Undetected: ${r.undetected}

📝 Reason:
${d.reasons || "Analysis completed."}

⚠️ Do not open or interact with this link.`;

const ci = r.community_intelligence || null;
let community_section_text = '';
if (ci && ci.previously_reported === true) {
  community_section_text = '\n\n━━━━━━━━━━━━━━━━━━\n🌐 COMMUNITY INTELLIGENCE\n━━━━━━━━━━━━━━━━━━\n\nIndicator: ' + (ci.normalized_value || 'N/A') + '\nPreviously reported: Yes\nCommunity reports: ' + ci.report_count + '\nFirst seen: ' + (ci.first_seen || 'N/A') + '\nLast seen: ' + (ci.last_seen || 'N/A');
}

return [{
  json: {
    ...d,
    community_intelligence: ci,
    community_section_text: community_section_text,
    response: (response || '') + community_section_text
  }
}];

