const original = $('HTTP Request3').first().json;
const lookup = $input.first().json;

// Check if there is a URL to look up
const url = (original.extracted_entities && original.extracted_entities.urls && original.extracted_entities.urls[0]) || null;

let community_intelligence;
let community_section_text = '';

if (!url) {
  // No URL in message — neutral defaults, no community section
  community_intelligence = {
    indicator_type: null,
    normalized_value: null,
    previously_reported: false,
    report_count: 0,
    first_seen: null,
    last_seen: null
  };
} else if (lookup && lookup.error !== undefined) {
  // Supabase failure — preserve original fields, set error flag
  return [{
    json: {
      ...original,
      community_intelligence_error: true,
      community_intelligence_error_message: typeof lookup.error === 'string' ? lookup.error : JSON.stringify(lookup.error),
      community_section_text: ''
    }
  }];
} else {
  const reportCount = (lookup && lookup.report_count !== undefined && lookup.report_count !== null)
    ? Number(lookup.report_count)
    : 0;
  const hasMatch = reportCount > 0;
  community_intelligence = hasMatch
    ? {
        indicator_type: lookup.indicator_type || 'URL',
        normalized_value: lookup.normalized_value || url,
        previously_reported: true,
        report_count: reportCount,
        first_seen: lookup.first_seen || null,
        last_seen: lookup.last_seen || null
      }
    : {
        indicator_type: 'URL',
        normalized_value: url,
        previously_reported: false,
        report_count: 0,
        first_seen: null,
        last_seen: null
      };
  if (hasMatch) {
    community_section_text = '\n\n━━━━━━━━━━━━━━━━━━\n🌐 COMMUNITY INTELLIGENCE\n━━━━━━━━━━━━━━━━━━\n\nIndicator: ' + (community_intelligence.normalized_value || 'N/A') + '\nPreviously reported: Yes\nCommunity reports: ' + community_intelligence.report_count + '\nFirst seen: ' + (community_intelligence.first_seen || 'N/A') + '\nLast seen: ' + (community_intelligence.last_seen || 'N/A');
  }
}

return [{
  json: {
    ...original,
    community_intelligence: community_intelligence,
    community_section_text: community_section_text
  }
}];
